 "content": "from collections import deque, Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and g[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if len(cells) == len(border) and all(g[y][x] == color for y,x in border):
                frames.append((r0,r1,c0,c1,color))
    frame_cells = set()
    for r0,r1,c0,c1,_ in frames:
        frame_cells.update((r,c) for r in range(r0,r1+1) for c in range(c0,c1+1))
    counts = Counter(g[r][c] for r in range(h) for c in range(w)
                     if g[r][c] != 0 and (r,c) not in frame_cells)
    marker_colors = [color for color,n in counts.items() if n > 0]
    # Assign each frame the scattered marker color whose count best matches
    # the number of cells in its top-left-anchored checkerboard fill.
    remaining = set(marker_colors)
    for r0,r1,c0,c1,_ in sorted(frames, key=lambda f: (f[0],f[2])):
        candidates = [c for c in remaining]
        if not candidates:
            continue
        target = sum(1 for r in range(r0+1,r1) for col in range(c0+1,c1)
                     if ((r-(r0+1))+(col-(c0+1))) %  2 == 0)
        color = min(candidates, key=lambda c: (abs(counts[c]-target), -counts[c]))
        remaining.remove(color)
        for r in range(r0+1,r1):
            for col in range(c0+1,c1):
                if ((r-(r0+1))+(col-(c0+1))) % 2 == 0:
                    g[r][col] = color
    # Erase all scattered clue pixels outside the frames.
    for r in range(h):
        for c in range(w):
            if (r,c) not in frame_cells and g[r][c] != 0:
                g[r][c] = 0
    return g
